export class AnalyticsManager {
  static async logUsage(params: {
    endpoint: string;
    model: string;
    isCacheHit: boolean;
    processingTimeMs: number;
    metadata?: any;
  }) {
    try {
      console.log("[Analytics]", JSON.stringify({
        ...params,
        timestamp: new Date().toISOString()
      }));
    } catch (error) {
      console.error("Analytics logging error:", error);
    }
  }
}
